ALTER TABLE `tasks` MODIFY `source_type` ENUM('manual','sourcing_purchase','automation') NOT NULL DEFAULT 'manual';
CREATE TABLE `automation_rules` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(200) NOT NULL,`trigger_event_type` ENUM('approval.overdue','approval.node.rejected','competitor.alert.queued','task.created') NOT NULL,`condition_severity` ENUM('any','info','warning','critical') NOT NULL DEFAULT 'any',`action_type` ENUM('notify_owner','create_task') NOT NULL,`owner_id` CHAR(36) CHARACTER SET ascii NOT NULL,`action_assignee_id` CHAR(36) CHARACTER SET ascii NULL,`action_title` VARCHAR(200) NOT NULL,`rate_limit_count` INT UNSIGNED NOT NULL,`rate_limit_window_minutes` INT UNSIGNED NOT NULL,`status` ENUM('active','paused') NOT NULL DEFAULT 'active',`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_automation_rules_scope_trigger`(`organization_id`,`workspace_id`,`status`,`trigger_event_type`),CONSTRAINT `fk_automation_rule_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_automation_rule_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_automation_rule_owner` FOREIGN KEY(`owner_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_automation_rule_assignee` FOREIGN KEY(`action_assignee_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_automation_rule_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `automation_executions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`rule_id` CHAR(36) CHARACTER SET ascii NOT NULL,`rule_version` INT UNSIGNED NOT NULL,`notification_id` CHAR(36) CHARACTER SET ascii NOT NULL,`status` ENUM('queued','leased','succeeded','rate_limited','retry_scheduled','dead_letter') NOT NULL DEFAULT 'queued',`attempt_count` INT UNSIGNED NOT NULL DEFAULT 0,`available_at` DATETIME(3) NOT NULL,`leased_by` VARCHAR(120) CHARACTER SET ascii NULL,`lease_expires_at` DATETIME(3) NULL,`action_resource_type` VARCHAR(40) CHARACTER SET ascii NULL,`action_resource_id` CHAR(36) CHARACTER SET ascii NULL,`last_error_code` VARCHAR(80) CHARACTER SET ascii NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_automation_rule_notification`(`rule_id`,`notification_id`),KEY `idx_automation_execution_claim`(`status`,`available_at`,`lease_expires_at`),KEY `idx_automation_execution_scope`(`organization_id`,`workspace_id`,`rule_id`,`updated_at`),CONSTRAINT `fk_automation_execution_rule` FOREIGN KEY(`rule_id`) REFERENCES `automation_rules`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_automation_execution_notification` FOREIGN KEY(`notification_id`) REFERENCES `notifications`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `automation_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(160) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(128) CHARACTER SET ascii NOT NULL,`rule_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_automation_operations`(`actor_id`,`route_key`,`idempotency_key`),CONSTRAINT `fk_automation_operation_rule` FOREIGN KEY(`rule_id`) REFERENCES `automation_rules`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
